SOURCE='import sys\nsys.setrecursionlimit(1000000)\n\ndef merge_sort(arr):\n    n = len(arr)\n    if n <= 1:\n        return arr, 0\n\n    mid = n // 2\n    left, cnt1 = merge_sort(arr[:mid])\n    right, cnt2 = merge_sort(arr[mid:])\n\n    i = j = 0\n    merged = []\n    cnt = cnt1 + cnt2\n\n    while i < len(left) and j < len(right):\n        if left[i] <= right[j]:\n            merged.append(left[i])\n            i += 1\n        else:\n            merged.append(right[j])\n            cnt += len(left) - i\n            j += 1\n\n    merged.extend(left[i:])\n    merged.extend(right[j:])\n\n    return merged, cnt\n\n\ndef main():\n    input = sys.stdin.readline\n    n = int(input())\n    v = [int(input()) for _ in range(n)]\n\n    # 转成负数，把 v[i] < v[j] 转成逆序对\n    arr = [-x for x in v]\n\n    _, ans = merge_sort(arr)\n    print(ans)\n\n\nif __name__ == "__main__":\n    main()\n'
with tempfile.NamedTemporaryFile('w',suffix='.py') as f:
 f.write(SOURCE); f.flush()
 root=Path(__file__).parent/'data'
 for i,c in enumerate(CASES):
  o=subprocess.run(['python3',f.name],input=c,text=True,capture_output=True,check=True).stdout
